    /**
     * Method to retrieve the Bank via an FindBankQuery
     * @return 	query	FindBankQuery
     */
    @SuppressWarnings("unused")
    public Bank find( UUID id ) {
    	LOGGER.info("handling find using " + id.toString() );
    	try {
    		return repository.findById(id).get();
    	}
    	catch( IllegalArgumentException exc ) {
    		LOGGER.warn( "Failed to find a Bank - {0}", exc.getMessage() );
    	}
    	return null;
    }
    
    /**
     * Method to retrieve a collection of all Banks
     *
     * @param	query	FindAllBankQuery 
     * @return 	List<Bank> 
     */
    @SuppressWarnings("unused")
    public List<Bank> findAll( FindAllBankQuery query ) {
    	LOGGER.info("handling findAll using " + query.toString() );
    	try {
    		return repository.findAll();
    	}
    	catch( IllegalArgumentException exc ) {
    		LOGGER.warn( "Failed to find all Bank - {0}", exc.getMessage() );
    	}
    	return null;
    }


